regex_blocks_parser_passes.command:
for d in ~/.subfleet/*; do :; done
{
for d in src; do :; done
} | cat
rg foo "$d"

f() {
for d in ~/.subfleet/*; do :; done
}
d=src
f
rg foo "$d"

for d in src; do :; done
time { d=~/.subfleet; }
rg foo "$d"

f() {
  d=/
}
for d in src; do :; done
f
rg foo "$d"

for d in ~/.subfleet/*; do :; done
time { false && d=src; }
rg foo "$d"
